      'kbn.fr': 'Disposition de référence (AZERTY français PC).',
      'kbn.be': 'Diffère du français sur 2 touches : <b>§</b> et <b>!</b> remplacent <b>-</b> et <b>_</b> sur la rangée des chiffres.',
      'kbn.mac': 'Diffère du français sur 3 touches (comme le belge) : <b>§</b>/<b>!</b> remplacent <b>-</b>/<b>_</b>, et <b>=</b>/<b>+</b> remplace <b>!</b>/<b>§</b> en bas à droite ; <b>œ</b> s\'obtient avec <b>Option (⌥) + O</b>.',
      'kbn.nf': 'Norme officielle depuis 2019 : <b>différente</b> de l\'AZERTY historique que la plupart des claviers vendus utilisent encore. Les chiffres s\'obtiennent avec <b>Maj</b> (les lettres accentuées à/é/è/ê sont en accès direct), et plusieurs lettres changent de position.',
      'kbn.n40': '<b>Sur un 40 %</b>, les chiffres et la rangée de fonction n\'ont pas de touche dédiée : on y accède via une touche Fn (couche secondaire), non représentée ici.',
      'kbn.mac_note': '<b>Clavier Mac</b> : fn/control/option/command remplacent Ctrl/Alt/AltGr/Menu, et il n\'y a jamais de bloc navigation dédié sur un clavier Apple (juste les flèches).',
      'kbn.cluster': '<b>Pg.préc/Pg.suiv</b> sont à la hauteur de la rangée Ctrl (pas Maj), et <b>◀/▼/▶</b> sont dans une 7<sup>e</sup> rangée qui déborde sous le clavier — vérifié sur photo, la forme exacte varie un peu d\'un fabricant à l\'autre.',
      'kbn.half': '<b>Pg.préc/Pg.suiv</b> n\'existent pas sur ce format : elles passent par la couche Fn. Le cluster de flèches demi-hauteur est un motif répandu (Dell XPS et équivalents) mais varie un peu d\'un fabricant à l\'autre.',
