      'intro.before': 'Avant de commencer',
      'intro.h': 'Comment bien apprendre à taper ?',
      'intro.r1': '<strong>La position de repos</strong>Les doigts gauches reposent sur {left}, les droits sur {right}. Tu sentiras deux petits reliefs sous les index (F et J) : c\'est ton point d\'ancrage. Reviens toujours ici après chaque frappe.',
      'intro.r2': '<strong>Regarde l\'écran, pas tes doigts</strong>C\'est la règle la plus importante. Regarder le clavier te force à mémoriser visuellement : regarder l\'écran force ta mémoire musculaire. C\'est elle qui te rendra rapide.',
      'intro.r3': '<strong>La lenteur avant la vitesse</strong>Taper lentement et juste vaut mieux que taper vite et faux. Chaque erreur crée une mauvaise habitude. La vitesse vient naturellement une fois les gestes mémorisés.',
      'intro.r4': '<strong>Un doigt, une touche</strong>Chaque touche est assignée à un doigt précis. Respecter ces assignations, même au début quand c\'est lent, est ce qui construira une technique solide sur le long terme.',
      'intro.go': 'Je suis prêt : commencer la première leçon →',
