      'sm.l1.name': 'Hover',
      'sm.l1.tag': 'Aim with the mouse',
      'sm.l1.brief': 'Circles appear. <b>Rest the cursor on one</b> and hold it there for a moment: no need to click.',
      'sm.l2.name': 'Click',
      'sm.l2.tag': 'Aim and click',
      'sm.l2.brief': 'This time you need to <b>click</b> the targets. They shrink as time passes: be quick.',
      'sm.l3.name': 'Bullseye',
      'sm.l3.tag': 'Aim for the centre',
      'sm.l3.brief': 'Every target has a <b style="color:#FFD84D">golden heart</b>, smaller than the target. Hitting it scores <b>3 points</b> instead of one, and <b>5 hearts in a row win back a life</b>.',
      'sm.l4.name': 'Quick targets',
      'sm.l4.tag': 'React fast',
      'sm.l4.brief': 'Targets only stay for a <b>brief moment</b>. Chain them together without hesitating to keep up the rhythm.',
      'sm.l5.name': 'Traps',
      'sm.l5.tag': 'Don’t click just anything',
      'sm.l5.brief': 'The <b style="color:#1FA971">green</b> ones score, the <b style="color:#E5484D">red</b> ones cost you points. But they don’t all look alike: <b>read before you click</b>.',
      'sm.l6.name': 'Bonuses & choices',
      'sm.l6.tag': 'Choose wisely',
      'sm.l6.brief': 'Special targets appear: <b style="color:#3B82F6">blue</b> = double points for a while, <b style="color:#A855F7">purple</b> = +2 s on the clock, <b style="color:#FFD84D">gold</b> = a brief jackpot. They vanish fast: <b>is it better to chase one or stay on the green ones?</b>',
      'sm.l7.name': 'Quick traps',
      'sm.l7.tag': 'Decide fast and right',
      'sm.l7.brief': 'Disguised traps <b>and</b> hurried targets, with the bonuses on top. You have to read them instantly.',
      'sm.l8.name': 'Drag and drop',
      'sm.l8.tag': 'Grab and drop',
      'sm.l8.brief': 'Grab each shape and <b>drag it</b> to the zone of its colour, without letting go of the button.',
      'sm.l9.name': 'Quick sort',
      'sm.l9.tag': 'Sort under pressure',
      'sm.l9.brief': 'Like drag and drop, but with <b>three colours</b> and a tighter clock. Sort quickly and accurately.',
      'sm.l10.name': 'ZQSD only',
      'sm.l10.tag': 'Learn to move around',
      'sm.l10.brief': 'Put the mouse down. Move your character with <b>Z Q S D</b> to <b>enter the green circles</b> and dodge the red zones.',
      'sm.l11.name': 'Mouse + keyboard',
      'sm.l11.tag': 'Everything at once',
      'sm.l11.brief': 'Move with <b>Z Q S D</b> to dodge the red zones, <b>while clicking</b> the targets and their hearts.',
      'sm.l12.name': 'Chaos',
      'sm.l12.tag': 'The full works',
      'sm.l12.brief': 'Everything at once, and faster: hearts, disguised traps, bonuses, movement and moving zones. The ultimate coordination test.',
      'sm.ch0.t': 'Aim',
      'sm.ch0.d': 'Hover, click, accuracy, speed',
      'sm.ch1.t': 'Decide',
      'sm.ch1.d': 'Traps and bonuses: read before you click',
      'sm.ch2.t': 'Drag',
      'sm.ch2.d': 'Grab it and drop it in the right place',
      'sm.ch3.t': 'On the keyboard',
      'sm.ch3.d': 'Z Q S D to move around',
      'sg.1.hint': 'Rest the cursor on a circle and hold it there until the ring is full',
      'sg.1.h1': 'A circle appears: <b>rest your cursor on it</b>, without clicking.',
      'sg.1.h2': 'Keep it still until <b>the white ring is full</b>.',
      'sg.1.h3': 'The longer your streak, the faster it locks on.',
      'sg.1.l1': 'Circle to lock on: 1 point',
      'sg.1.l2': 'White dot in the centre: 3 points',
      'sg.1.l3': 'Blue circle: double points for 5 s',
