      'mascot.idea': 'KeyPace mascot with a raised index finger, sitting with a laptop',
      'mascot.cheer': 'KeyPace mascot raising a fist to celebrate, with a laptop',
      'kbn.fr': 'Reference layout (French PC AZERTY).',
      'kbn.be': 'Differs from the French layout on 2 keys: <b>§</b> and <b>!</b> replace <b>-</b> and <b>_</b> on the number row.',
      'kbn.mac': 'Differs from the French layout on 3 keys (like the Belgian one): <b>§</b>/<b>!</b> replace <b>-</b>/<b>_</b>, and <b>=</b>/<b>+</b> replaces <b>!</b>/<b>§</b> at the bottom right; <b>œ</b> is typed with <b>Option (⌥) + O</b>.',
      'kbn.nf': 'Official standard since 2019: <b>different</b> from the historical AZERTY that most keyboards sold still use. Digits are typed with <b>Shift</b> (the accented letters à/é/è/ê are directly accessible), and several letters change position.',
      'kbn.n40': '<b>On a 40% keyboard</b>, the digits and the function row have no dedicated key: you reach them through an Fn key (secondary layer), not shown here.',
      'kbn.mac_note': '<b>Mac keyboard</b>: fn/control/option/command replace Ctrl/Alt/AltGr/Menu, and an Apple keyboard never has a dedicated navigation block (just the arrows).',
      'kbn.cluster': '<b>Page Up/Page Down</b> sit level with the Ctrl row (not Shift), and <b>◀/▼/▶</b> are in a 7<sup>th</sup> row that hangs below the keyboard. Checked against photos; the exact shape varies a little from one manufacturer to another.',
      'kbn.half': '<b>Page Up/Page Down</b> do not exist on this format: they go through the Fn layer. The half-height arrow cluster is a common pattern (Dell XPS and similar) but varies a little from one manufacturer to another.',
      'kbp.shift': 'shift',
      'kbp.enter': 'enter',
      'kbp.space': 'space',
      'kbp.numlock': 'num',
      'kbp.del': 'Del',
      'kbp.ins': 'Ins',
      'kbp.home': 'Home',
      'kbp.end': 'End',
      'kbp.pgup': 'PgUp',
      'kbp.pgdn': 'PgDn',
      'intro.before': 'Before you start',
      'intro.h': 'How do you learn to type well?',
      'intro.r1': '<strong>The resting position</strong>Your left fingers rest on {left}, your right ones on {right}. You will feel two small bumps under your index fingers (F and J): they are your anchor point. Always come back here after each keystroke.',
      'intro.r2': '<strong>Look at the screen, not at your fingers</strong>This is the most important rule. Looking at the keyboard makes you memorise visually: looking at the screen builds your muscle memory. That is what will make you fast.',
      'intro.r3': '<strong>Slow before fast</strong>Typing slowly and correctly is better than typing fast and wrong. Every mistake creates a bad habit. Speed comes naturally once the movements are memorised.',
      'intro.r4': '<strong>One finger, one key</strong>Each key is assigned to a specific finger. Sticking to these assignments, even at the start when it feels slow, is what will build a solid technique in the long run.',
      'intro.go': 'I’m ready: start the first lesson →',
