      'sm.l1.name': 'Zweven',
      'sm.l1.tag': 'Richt met de muis',
      'sm.l1.brief': 'Er verschijnen cirkels. <b>Zet de cursor erop</b> en houd hem even stil: klikken hoeft niet.',
      'sm.l2.name': 'Klik',
      'sm.l2.tag': 'Richt en klik',
      'sm.l2.brief': 'Nu moet je op de doelen <b>klikken</b>. Ze worden na een tijdje kleiner: wees snel.',
      'sm.l3.name': 'Midden in de roos',
      'sm.l3.tag': 'Richt op het midden',
      'sm.l3.brief': 'Elk doel heeft een <b style="color:#FFD84D">gouden hart</b>, kleiner dan het doel zelf. Raak je het, dan krijg je <b>3 punten</b> in plaats van 1, en <b>5 harten op rij geven een leven terug</b>.',
      'sm.l4.name': 'Snelle doelen',
      'sm.l4.tag': 'Reageer snel',
      'sm.l4.brief': 'De doelen blijven maar een <b>korte tijd</b> staan. Klik door zonder te aarzelen om het tempo vast te houden.',
      'sm.l5.name': 'Valstrikken',
      'sm.l5.tag': 'Klik niet zomaar op alles',
      'sm.l5.brief': 'De <b style="color:#1FA971">groene</b> leveren punten op, de <b style="color:#E5484D">rode</b> kosten je punten. Maar ze lijken niet allemaal op elkaar: <b>lees voor je klikt</b>.',
      'sm.l6.name': 'Bonus & keuzes',
      'sm.l6.tag': 'Kies slim',
      'sm.l6.brief': 'Er verschijnen speciale doelen: <b style="color:#3B82F6">blauw</b> = dubbele punten voor even, <b style="color:#A855F7">paars</b> = +2 s op de timer, <b style="color:#FFD84D">goud</b> = korte jackpot. Ze verdwijnen snel: <b>kun je ze beter najagen of bij de groene blijven?</b>',
      'sm.l7.name': 'Snelle valstrikken',
      'sm.l7.tag': 'Beslis snel en juist',
      'sm.l7.brief': 'Vermomde valstrikken <b>en</b> haastige doelen, samen met de bonussen. Je moet in één oogopslag kunnen lezen.',
      'sm.l8.name': 'Slepen en neerzetten',
      'sm.l8.tag': 'Pak en zet neer',
      'sm.l8.brief': 'Pak elke vorm vast en <b>sleep hem</b> naar het vak met dezelfde kleur, zonder de knop los te laten.',
      'sm.l9.name': 'Snel sorteren',
      'sm.l9.tag': 'Sorteer onder druk',
      'sm.l9.brief': 'Zoals slepen en neerzetten, maar met <b>drie kleuren</b> en een strakkere timer. Ruim snel en juist op.',
      'sm.l10.name': 'Alleen ZQSD',
      'sm.l10.tag': 'Leer je verplaatsen',
      'sm.l10.brief': 'Laat de muis liggen. Verplaats je personage met <b>Z Q S D</b> om <b>in de groene cirkels te gaan</b> en de rode zones te ontwijken.',
